type ReclaimStaleClickUpDraftPostsParams struct {
	Before  pgtype.Timestamptz
	MaxRows int32
}

// Posts interrupted before they finished (a crash mid-confirm): the caller
// finishes them with the same idempotency key, so nothing posts twice.
func (q *Queries) ReclaimStaleClickUpDraftPosts(ctx context.Context, arg ReclaimStaleClickUpDraftPostsParams) ([]ClickupDraft, error) {
	rows, err := q.db.Query(ctx, reclaimStaleClickUpDraftPosts, arg.Before, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ClickupDraft
	for rows.Next() {
		var i ClickupDraft
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.IntegrationID,
			&i.ChatID,
			&i.ThreadID,
			&i.TaskID,
			&i.ParentCommentID,
			&i.MentionUserIds,
			&i.NewStatus,
			&i.Body,
			&i.BodySha256,
			&i.State,
			&i.Source,
			&i.ExecutionID,
			&i.PlanTaskKey,
			&i.PreviewMessageID,
			&i.PostedCommentID,
			&i.ReasonCode,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reviseClickUpDraft = `-- name: ReviseClickUpDraft :one
UPDATE public.clickup_drafts
SET body = $1::text, body_sha256 = $2, preview_message_id = 0, updated_at = now()
WHERE workspace_id = $3 AND id = $4 AND state = 'pending'
  AND body_sha256 = $5 AND expires_at > $6::timestamptz
RETURNING id, workspace_id, integration_id, chat_id, thread_id, task_id, parent_comment_id, mention_user_ids, new_status, body, body_sha256, state, source, execution_id, plan_task_key, preview_message_id, posted_comment_id, reason_code, expires_at, created_at, updated_at, finished_at
`

type ReviseClickUpDraftParams struct {
	Body        string
	BodySha256  string
	WorkspaceID pgtype.UUID
	ID          int64
	OldSha256   string
	AtTime      pgtype.Timestamptz
}

// Replaces the body of a pending, unexpired draft whose body is still the
// one the owner edited; the old preview stops being valid.
func (q *Queries) ReviseClickUpDraft(ctx context.Context, arg ReviseClickUpDraftParams) (ClickupDraft, error) {
	row := q.db.QueryRow(ctx, reviseClickUpDraft,
		arg.Body,
		arg.BodySha256,
		arg.WorkspaceID,
		arg.ID,
		arg.OldSha256,
		arg.AtTime,
	)
	var i ClickupDraft
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IntegrationID,
		&i.ChatID,
		&i.ThreadID,
		&i.TaskID,
		&i.ParentCommentID,
		&i.MentionUserIds,
		&i.NewStatus,
		&i.Body,
		&i.BodySha256,
		&i.State,
		&i.Source,
		&i.ExecutionID,
		&i.PlanTaskKey,
		&i.PreviewMessageID,
		&i.PostedCommentID,
		&i.ReasonCode,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FinishedAt,
	)
	return i, err
}

const setClickUpDraftPreview = `-- name: SetClickUpDraftPreview :execrows
UPDATE public.clickup_drafts SET preview_message_id = $1::bigint, updated_at = now()
WHERE workspace_id = $2 AND id = $3 AND state IN ('pending', 'failed')
`

type SetClickUpDraftPreviewParams struct {
	MessageID   int64
	WorkspaceID pgtype.UUID
	ID          int64
}

// Binds the preview message that carries the draft's current buttons.
func (q *Queries) SetClickUpDraftPreview(ctx context.Context, arg SetClickUpDraftPreviewParams) (int64, error) {
	result, err := q.db.Exec(ctx, setClickUpDraftPreview, arg.MessageID, arg.WorkspaceID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
